import { expect, it } from "vitest";
import { lineText, prepare, solve, withHyphenation, withOpticalMargins } from "../src/engine";
import { compileStatic } from "../src/static";

const measure = (text: string) => [...text].reduce((sum, c) => sum + (c === " " ? 4 : 8), 0);
const p = withOpticalMargins(withHyphenation(prepare("Thus, building responsive paragraphs requires careful typesetting. Keep every source word intact.", measure), word => word === "typesetting." ? ["type", "set", "ting."] : [word], measure), () => ({ start: 1, end: 2 }));

it("covers every sampled measure once, coalescing identical plans without losing hyphens or source", () => {
  const bands = compileStatic(p, 90, 400, .5);
  expect(bands.length).toBeLessThan(621);
  expect(bands.some(b => b.lines?.some(l => l.line.hyphenated))).toBe(true);
  for (let width = 90; width <= 400; width += .5) {
    const selected = bands.filter(b => b.min <= width && b.max > width);
    expect(selected.length).toBe(1);
    const actual = selected[0].lines?.map(l => lineText(p, l.line));
    const layout = solve(p, width);
    expect(actual).toEqual(layout.lines.some(l => Math.abs(l.residual) > .5) ? undefined : layout.lines.map(l => lineText(p, l)));
  }
});

it("retains native fallback for unfit text and validates sampled ranges", () => {
  const word = prepare("Indivisible", measure);
  expect(compileStatic(word, 20, 30)).toEqual([{ min: 20, max: 31, lines: null }]);
  for (const args of [[0, 100, 1], [100, 99, 1], [50, 100, 0], [50, Infinity, 1], [50, 100, NaN], [50, 100, Number.MIN_VALUE]]) expect(() => compileStatic(p, ...args as [number, number, number])).toThrow(RangeError);
  expect(() => compileStatic(p, 90, 100, 1, { shrink: 2 })).toThrow(RangeError);
});

import { expect, it } from "vitest";
import { lineText, prepare, solve, withHyphenation, type Run } from "../src/engine";

// Sans: 8px letters and 4px spaces. Code: a wider monospace, 10px for everything.
type Style = "code";
const measure = (text: string, style?: Style) => [...text].reduce((n, c) => n + (style === "code" ? 10 : c === " " ? 4 : 8), 0);
const runs: Run<Style>[] = [{ text: "Run " }, { text: "run", style: "code" }, { text: ", then run it." }];

it("measures each piece of a word in its own run's style, caching by style and text", () => {
  const calls: [string, Style | undefined][] = [];
  const p = prepare(runs, (text, style) => { calls.push([text, style]); return measure(text, style); });
  expect(p.words).toEqual(["Run", "run,", "then", "run", "it."]);
  const widths = p.words.map((_, i) => p.widths[i + 1] - p.widths[i]);
  // "run" in code is 30px; the same text in sans is 24px. "run," joins a code piece and a sans comma.
  expect(widths).toEqual([24, 38, 32, 24, 24]);
  expect(calls).toContainEqual(["run", "code"]);
  expect(calls).toContainEqual(["run", undefined]);
  expect(new Set(calls.map(c => c.join("|"))).size).toBe(calls.length);
  expect(p.space).toBe(4);
  expect([...p.endHangs]).toEqual([0, 8, 0, 0, 8]);
});

it("maps every word, gap and line back to offsets in the joined source", () => {
  const source = runs.map(run => run.text).join("");
  const p = prepare(runs, measure);
  expect(p.starts).toEqual([0, 4, 9, 14, 18]);
  p.words.forEach((word, i) => expect(source.slice(p.starts![i], p.starts![i] + word.length)).toBe(word));
  const { lines } = solve(p, 90, { tracking: 0 });
  expect(lines.length).toBeGreaterThan(1);
  for (const line of lines) {
    const from = p.starts![line.start], to = p.starts![line.end - 1] + p.words[line.end - 1].length;
    expect(source.slice(from, to)).toBe(lineText(p, line));
  }
  // Plain text records the same offsets, through any run of whitespace.
  expect(prepare("  a\t\tbc  d", measure).starts).toEqual([2, 5, 9]);
});

it("keeps a run's nonbreaking spaces inside one word and offsets hyphenated breaks within it", () => {
  const input: Run<Style>[] = [{ text: "Then " }, { text: "bun\u00a0run\u00a0check", style: "code" }, { text: " before typesetting." }];
  const source = input.map(run => run.text).join("");
  const p = withHyphenation(prepare(input, measure), word => word === "typesetting." ? ["type", "set", "ting."] : [word], text => measure(text));
  expect(p.words).toEqual(["Then", "bun\u00a0run\u00a0check", "before", "typesetting."]);
  expect(p.widths[2] - p.widths[1]).toBe(130);
  const { lines } = solve(p, 120, { tracking: 0 });
  const split = lines.find(line => line.hyphenated)!;
  const from = p.starts![split.start] + (split.startOffset ?? 0), to = p.starts![split.end - 1] + split.endOffset!;
  expect(source.slice(from, to) + "-").toBe(lineText(p, split));
});

import { expect, it } from "vitest";
import { defaults, lineText, prepare, solve, withHyphenation, withOpticalMargins, type Layout } from "../src/engine";

const measure = (text: string) => [...text].reduce((sum, c) => sum + (c === " " ? 4 : 8), 0);
const jumps = (layout: Layout) => layout.lines.slice(1).filter((line, i) => Math.abs(line.fitness! - layout.lines[i].fitness!) > 1).length;

it("retains competing fitness histories and chooses a smoother complete paragraph", () => {
  const text = "A quiet paragraph can become much more comfortable when its lines share a reasonably even rhythm of spaces instead of alternating between very tight and very loose arrangements.";
  const p = prepare(text, measure);
  const independent = solve(p, 300, { adjacentPenalty: 0 });
  const adjacent = solve(p, 300);
  expect(jumps(independent)).toBe(3);
  expect(jumps(adjacent)).toBe(1);
  expect(adjacent.cost).toBeLessThan(independent.cost + jumps(independent) * defaults.adjacentPenalty);
  expect(adjacent.lines.map(line => lineText(p, line)).join(" ")).toBe(text);
  expect(adjacent.lines.reduce((sum, line) => sum + line.cost, 0)).toBeCloseTo(adjacent.cost, 8);
});

it("combines measured margins with punctuation and can disable only the optical model", () => {
  const p = withOpticalMargins(prepare("Thus.", measure), () => ({ start: 2, end: 3 }));
  const on = solve(p, 100).lines[0];
  expect([on.opening, on.hanging]).toEqual([2, 8]);
  const off = solve(p, 100, { protrusion: 0 }).lines[0];
  expect([off.opening, off.hanging]).toEqual([0, 8]);
  const half = solve(p, 100, { protrusion: 0.5, hanging: 0 }).lines[0];
  expect([half.opening, half.hanging]).toEqual([1, 1.5]);
});

it("measures continuation and hyphen edges once, without dropping original word measurements", () => {
  const original = withHyphenation(prepare("abcdefghijklmnopqr", measure), word => word.match(/.{3}/g)!, measure);
  let calls = 0;
  const p = withOpticalMargins(original, text => { calls++; return { start: text.startsWith("a") ? 1 : 2, end: text === "-" ? 4 : 0 }; });
  const count = calls;
  const layout = solve(p, 54, { tracking: 0 });
  expect(layout.lines.some(line => line.hyphenated)).toBe(true);
  for (const line of layout.lines) {
    expect(line.opening).toBe(line.startOffset ? 2 : 1);
    expect(line.hanging).toBe(line.hyphenated ? 4 : 0);
  }
  solve(p, 100); solve(p, 250);
  expect(calls).toBe(count);
  expect(p.widths).toBe(original.widths);
  expect(() => withOpticalMargins(original, () => ({ start: -1, end: 0 }))).toThrow(RangeError);
  expect(() => withOpticalMargins(original, () => ({ start: 0, end: Infinity }))).toThrow(RangeError);
  expect(() => solve(p, 100, { protrusion: 1.1 })).toThrow(RangeError);
});

import { expect, it } from "vitest";
import { lineText, prepare, solve, withHyphenation } from "../src/engine";
import { hyphenate, hyphenator } from "../src/english";

const measure = (text: string) => [...text].reduce((n, c) => n + (c === " " ? 4 : 8), 0);

it("hyphenates American English with TeX's patterns and exception list", () => {
  // Expected breaks are TeX's (ushyphmax), not derived from this implementation.
  expect(hyphenate("hyphenation")).toEqual(["hy", "phen", "ation"]);
  expect(hyphenate("configuration")).toEqual(["con", "fig", "u", "ra", "tion"]);
  expect(hyphenate("justification")).toEqual(["jus", "ti", "fi", "ca", "tion"]);
  expect(hyphenate("observability")).toEqual(["ob", "serv", "abil", "ity"]);
  expect(hyphenate("associate")).toEqual(["as", "so", "ciate"]);
  expect(hyphenate("present")).toEqual(["present"]);
  expect(hyphenate("Development")).toEqual(["De", "vel", "op", "ment"]);
});

it("keeps punctuation on the edge fragments and leaves code, numbers and short words whole", () => {
  expect(hyphenate("“configuration,”")).toEqual(["“con", "fig", "u", "ra", "tion,”"]);
  expect(hyphenate("(instrumentation)")).toEqual(["(in", "stru", "men", "ta", "tion)"]);
  expect(hyphenate("well-developed")).toEqual(["well-", "de", "vel", "oped"]);
  for (const word of ["cat", "useEffect", "HTTPS", "https://example.com", "v1.2.3", "snake_case", "naïveté", "10\u00a0km", "-foo", "--option"]) expect(hyphenate(word)).toEqual([word]);
  expect(hyphenator({ left: 3, right: 4 })("hyphenation")).toEqual(["hyphen", "ation"]);
  expect(hyphenator({ minWord: 12 })("hyphenation")).toEqual(["hyphenation"]);
});

it("plugs into withHyphenation, so a narrow column can break inside words", () => {
  const text = "Instrumentation and observability configuration";
  const p = withHyphenation(prepare(text, measure), hyphenate, measure);
  const { lines } = solve(p, 100, { tracking: 0 });
  expect(lines.some(line => line.hyphenated)).toBe(true);
  expect(lines.map(line => line.hyphenated ? lineText(p, line).slice(0, -1) : lineText(p, line) + " ").join("").trim()).toBe(text);
});

import { describe, expect, it } from "vitest";
import { defaults, lineText, prepare, solve, withHyphenation, withOpticalMargins, type Options } from "../src/engine";

// Deliberately non-additive shaping: measuring the hyphen separately is wrong.
const measure = (s: string) => [...s].reduce((n, c) => n + (c === " " ? 4 : 8), 0) - (s.match(/a-/g)?.length ?? 0) * 2;
const split = (word: string) => word.match(/.{1,3}/gu)!;
type Optical = (text: string, index: number) => { start: number; end: number };

// Enumerate partitions over source offsets, independently of the engine's word
// matrices and dynamic-programming nodes. Measure each displayed line directly.
function exhaustive(text: string, width: number, o: Options, emergency = false, optical?: Optical, count?: number): number {
  const breaks = [{ end: 0, next: 0, hyphen: false }];
  for (const match of text.matchAll(/[^ ]+/g)) {
    const parts = split(match[0]);
    let offset = match.index;
    for (const part of parts.slice(0, -1)) {
      offset += part.length;
      breaks.push({ end: offset, next: offset, hyphen: true });
    }
    const end = match.index + match[0].length;
    breaks.push({ end, next: Math.min(text.length, end + 1), hyphen: false });
  }
  let best = Infinity;
  function visit(start: number, total: number, previousFitness = 1, lines = 0) {
    if (start === breaks.length - 1) { if (count === undefined || lines === count) best = Math.min(best, total); return; }
    for (let end = start + 1; end < breaks.length; end++) {
      const a = breaks[start], b = breaks[end];
      const visible = text.slice(a.next, b.end) + (b.hyphen ? "-" : "");
      const last = end === breaks.length - 1, gaps = visible.split(" ").length - 1;
      const chars = [...visible].length, natural = measure(visible);
      const firstIndex = text.slice(0, a.next).split(" ").length - 1;
      const lastIndex = text.slice(0, b.end).split(" ").length - 1;
      const hanging = Math.max(b.hyphen ? 0 : measure(visible.match(/[.,;:!?…’”'"]+$/u)?.[0] ?? "") * o.hanging,
        (optical?.(visible.split(" ").at(-1)!, lastIndex).end ?? 0) * o.protrusion);
      const opening = optical ? optical(visible.split(" ")[0], firstIndex).start * o.protrusion
        : measure(visible.match(/^[“‘"'«‹]/u)?.[0] ?? "") * o.opening;
      const target = width + hanging + opening;
      const delta = last && natural <= target ? 0 : target - natural;
      const capacity = gaps * 4 * (delta < 0 ? o.shrink : o.stretch) + chars * o.tracking;
      const ratio = capacity ? Math.min(1, Math.abs(delta) / capacity) : 0;
      const signed = capacity ? delta / capacity : delta === 0 ? 0 : Math.sign(delta) * Infinity;
      const fitness = signed < -0.5 ? 0 : signed <= 0.5 ? 1 : signed <= 1 ? 2 : 3;
      let residual = delta - Math.sign(delta) * ratio * capacity;
      let strain = 100 * ratio ** 3;
      if (o.mode === "balanced") {
        strain = 100 * (ratio + Math.abs(residual) / Math.max(capacity, gaps * 4, 4)) ** 3;
        if (gaps) {
          const before = Math.sign(delta) * ratio * 4 * (delta < 0 ? o.shrink : o.stretch);
          residual -= (Math.max(-4 * o.shrink, before + residual / gaps) - before) * gaps;
        }
      }
      if (emergency && delta > 0) {
        const extra = Math.min(width * o.emergencyStretch, gaps * measure(" "));
        strain = 100 * (delta / Math.max(measure(" "), capacity + extra)) ** 3;
      }
      if (o.mode === "balanced" && o.emergencyStretch > 0 && !emergency && (delta > capacity * Math.cbrt(2) + 0.01 || Math.abs(residual) > 0.01)) continue;
      let cost = 1 + strain * (delta < 0 ? o.compressionPenalty : 1);
      if (Math.abs(residual) > 0.01) cost += o.mode === "balanced" && residual < 0
        ? 1e6 + 1e4 * residual ** 2 : 1e4 + 100 * residual ** 2;
      if (last && start > 0) {
        const missing = Math.max(0, width * o.lastLine - natural);
        cost += o.ending === "soft" ? o.widowPenalty * (missing / width) ** 2
          : o.widowPenalty / 300 * Math.min(10000, 100 * (missing / Math.max(4, gaps * 4 * o.stretch + chars * o.tracking)) ** 3);
      }
      cost += b.hyphen ? o.hyphenPenalty + (a.hyphen ? o.consecutiveHyphenPenalty : 0)
        : last && a.hyphen ? o.finalHyphenPenalty : 0;
      if (start && Math.abs(fitness - previousFitness) > 1) cost += o.adjacentPenalty;
      visit(end, total + cost, fitness, lines + 1);
    }
  }
  visit(0, 0);
  return best === Infinity && !emergency ? exhaustive(text, width, o, true, optical, count) : best;
}

describe("optional hyphenation", () => {
  it("matches exhaustive partitions including shaping, adjacency costs, and both fitting passes", () => {
    let seed = 17;
    const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 2 ** 32; };
    for (let i = 0; i < 100; i++) {
      const text = Array.from({ length: 2 + i % 3 }, () => "a".repeat(3 + Math.floor(random() * 7))).join(" ");
      const width = 30 + random() * 150;
      const o: Options = { ...defaults, mode: i % 2 ? "strict" : "balanced", ending: i % 3 ? "fit" : "soft", tracking: random(), shrink: random(), hyphenPenalty: random() * 100, consecutiveHyphenPenalty: random() * 300, finalHyphenPenalty: random() * 300 };
      const hyphenated = withHyphenation(prepare(text, measure), split, measure);
      const optical: Optical | undefined = i % 3 ? undefined : (text, index) => ({ start: 0.3 * (text.charCodeAt(0) % 5) + index * 0.1, end: text.endsWith("-") ? 2.5 : 0.4 * index });
      const p = optical ? withOpticalMargins(hyphenated, optical) : hyphenated;
      const result = solve(p, width, o);
      expect(result.cost, `case ${i}`).toBeCloseTo(exhaustive(text, width, o, false, optical), 5);
      let source = "";
      for (const [j, line] of result.lines.entries()) {
        const visible = lineText(p, line);
        if (j && !result.lines[j - 1].hyphenated) source += " ";
        source += line.hyphenated ? visible.slice(0, -1) : visible;
        expect(line.natural).toBeCloseTo(measure(visible), 8);
        expect(Math.abs(line.tracking)).toBeLessThanOrEqual(o.tracking + 1e-9);
        expect(line.wordSpacing).toBeGreaterThanOrEqual(-4 * o.shrink - 1e-9);
        if (!line.last || line.natural > width + line.hanging + line.opening) {
          expect(line.natural + line.wordSpacing * (line.end - line.start - 1) + line.tracking * [...visible].length + line.residual).toBeCloseTo(width + line.hanging + line.opening, 7);
        }
      }
      expect(source).toBe(text);
    }
  });

  it("matches exhaustive partitions with exactly the requested number of lines", () => {
    let seed = 23;
    const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 2 ** 32; };
    for (let i = 0; i < 60; i++) {
      const text = Array.from({ length: 2 + i % 3 }, () => "a".repeat(3 + Math.floor(random() * 7))).join(" ");
      const width = 30 + random() * 150;
      const p = withHyphenation(prepare(text, measure), split, measure);
      const breaks = p.words.length + p.hyphenation!.reduce((n, f) => n + (f ? f.offsets.length - 2 : 0), 0);
      const count = 1 + Math.floor(random() * Math.min(5, breaks));
      const o: Options = { ...defaults, mode: i % 2 ? "strict" : "balanced", tracking: random(), shrink: random() };
      const result = solve(p, width, { ...o, lines: count });
      expect(result.lines.length, `case ${i}`).toBe(count);
      expect(result.cost, `case ${i}`).toBeCloseTo(exhaustive(text, width, o, false, undefined, count), 5);
    }
  });

  it("can split one word on successive lines and retains exact source offsets", () => {
    const p = withHyphenation(prepare("abcdefghijklmnopqr", measure), split, measure);
    const result = solve(p, 56, { tracking: 0 });
    expect(result.lines.map(l => lineText(p, l))).toEqual(["abcdef-", "ghijkl-", "mnopqr"]);
